<fieldset class="admin-fieldset"><legend>Roles globales</legend><div class="admin-check-grid"><?php foreach ($roles as $role): $value = (int) $role['id'] . ':global'; ?><label class="admin-check"><input type="checkbox" name="role_assignments[]" value="<?= e($value) ?>" <?= isset($selectedRoles[$value]) ? 'checked' : '' ?>><span><strong><?= e($role['name']) ?></strong><small><?= e($role['code']) ?><?= (int) $role['is_system'] === 1 ? ' · Sistema' : '' ?></small></span></label><?php endforeach ?></div></fieldset>
<fieldset class="admin-fieldset"><legend>Acceso a sucursales</legend><?php if ($branches === []): ?><p class="admin-empty">No hay sucursales registradas.</p><?php else: ?><div class="admin-branch-assignments"><?php foreach ($branches as $branch): ?><article><label class="admin-check admin-branch-check"><input type="checkbox" name="branch_ids[]" value="<?= e($branch->id) ?>" <?= isset($selectedBranches[$branch->id]) ? 'checked' : '' ?>><span><strong><?= e($branch->name) ?></strong><small><?= e($branch->code) ?></small></span></label><div class="admin-inline-checks"><?php foreach ($roles as $role): $value = (int) $role['id'] . ':' . (int) $branch->id; ?><label><input type="checkbox" name="role_assignments[]" value="<?= e($value) ?>" <?= isset($selectedRoles[$value]) ? 'checked' : '' ?>> <?= e($role['name']) ?></label><?php endforeach ?></div></article><?php endforeach ?></div><?php endif ?></fieldset>
